class _FixedGoalRNG:
    """Stub RNG: makes place_obj put the goal exactly at (x, y) during _gen_grid."""
    def __init__(self, x, y):
        self._vals = [int(x), int(y)]
    def integers(self, low, high):
        return self._vals.pop(0)

