@patch
@torch.no_grad()
def evaluate_batch_fixed_t0(self: MultiAgentGoalEvaluator, episodes: dict,
                            pool: MultiAgentEnvPool, t0s, max_steps=150):
    """
    Receding-horizon MPC evaluation of N episodes in parallel.
    Goal = the green goal cell: the planner is conditioned on each agent's
    goal_obs (observation standing on the goal), and success is read from
    the env's own termination signal.
    """
    H = self.history_size
    N = pool.num_envs
    t0s = np.asarray(t0s)
    assert (t0s >= H - 1).all(), f"t0 too early for history_size={H}"

    # --- goal embeddings from goal_obs (same target the planner optimizes) ---
    goal_emb = {}
    for ai, agent in enumerate(self.agents):
        g = episodes["goal_obs"][:, ai].unsqueeze(1).to(self.device)   # (N, 1, C, H, W)
        enc = self.model.encode({"pixels": g})
        goal_emb[agent] = enc["emb"][:, 0]                             # (N, D)

    # --- reset, then force each env to its recorded config ---
    # pool.reset(seed=0)
    # --- reproduce each recorded layout ---
    # 1) pin every env's goal RNG so _gen_grid places the goal on the recorded cell
    goal_pos_list = episodes["goal_pos"].tolist()
    for i in range(N):
        gx, gy = (int(v) for v in goal_pos_list[i])
        pool.envs[i].env.unwrapped._goal_rng = _FixedGoalRNG(gx, gy)

    # 2) ONE pool-level reset. Seed must be a LIST: an int would be
    #    incremented per env by _broadcast_arg (env i would get seed+i).
    #    This call also allocates pool._stacked_infos (fixes the None crash).
    pool.reset(seed=[0] * N)

    # 3) verify pinning worked, then overwrite agent positions/directions
    logger.info(f"Setting {N} envs to their recorded states at t0...")
    for i in range(N):
        unwrapped = pool.envs[i].env.unwrapped
        gx, gy = (int(v) for v in goal_pos_list[i])
        assert tuple(unwrapped.goal_pos) == (gx, gy), \
            f"env {i}: goal pinning failed, got {tuple(unwrapped.goal_pos)} vs {(gx, gy)}"

        agent_positions = {a: episodes[a]["pos_t0"][i].tolist() for a in self.agents}
        agent_directions = {a: int(episodes[a]["dir_t0"][i].item()) for a in self.agents}
        set_env_state(pool, i, goal_pos_list[i], agent_positions, agent_directions, self.agents)
        
    goal_pos_list = episodes["goal_pos"].tolist()
    logger.info(f"Setting {N} envs to their recorded states at t0...")
    for i in range(N):
        agent_positions = {a: episodes[a]["pos_t0"][i].tolist() for a in self.agents}
        agent_directions = {a: int(episodes[a]["dir_t0"][i].item()) for a in self.agents}
        set_env_state(pool, i, goal_pos_list[i], agent_positions, agent_directions, self.agents)

    # --- initial per-agent info (message used only for the first plan) ---
    info = {}
    for agent in self.agents:
        partner = [a for a in self.agents if a != agent][0]
        info[agent] = self._build_agent_info_batch(episodes, agent, partner)

    results = {agent: {"step": [], "embedding_dist_to_goal": [], "reached": []}
               for agent in self.agents}
    alive = {agent: np.ones(N, dtype=bool) for agent in self.agents}

    for real_step in range(max_steps):
        logger.info(f"Real step {real_step}/{max_steps} -- alive agents: "
                    f"{[alive[a].sum() for a in self.agents]}")
        env_mask = alive[self.agents[0]] | alive[self.agents[1]]
        if not env_mask.any():
            break

        actions = {}
        for agent in self.agents:
            _, plan = self.planners[agent].plan(info[agent])   # (N, horizon)
            act = plan[:, 0].cpu().numpy()
            actions[agent] = np.where(alive[agent], act, self.noop_action)

        _, rewards, terminateds, truncateds, stacked_infos = pool.step(
            actions, mask=env_mask, noop_action=self.noop_action
        )
        # ---- DIAGNOSTIC: ground-truth positions vs goal ----
        for i in range(N):
            if not env_mask[i]:
                continue
            for agent in self.agents:
                pos = tuple(int(v) for v in pool.envs[i].env.unwrapped.agents[agent].state.pos)
                gp = goal_pos_list[i]
                d = abs(pos[0] - gp[0]) + abs(pos[1] - gp[1])
                logger.info(
                    f"[DIAG] step {real_step} env {i} agent {agent}: "
                    f"pos={pos} act={actions[agent][i]} L1_to_goal={d} "
                    f"term={bool(terminateds[agent][i])}"
                )
        # ---- END DIAGNOSTIC ----

        for agent in self.agents:
            for i in range(N):
                if not alive[agent][i] or not env_mask[i]:
                    continue

                # --- success straight from the env ---
                reached = bool(terminateds[agent][i])
                truncated = bool(truncateds[agent][i])

                pov = stacked_infos[agent]["pov"][i, 0]
                frame = (self.data_module.val_receiver_transform(pov)
                         .unsqueeze(0).unsqueeze(0).to(self.device))
                enc = self.model.encode({"pixels": frame})
                cur_emb = enc["emb"][:, 0]
                dist = F.mse_loss(cur_emb, goal_emb[agent][i:i + 1],
                                  reduction="none").sum(-1)

                results[agent]["step"].append((i, real_step))
                results[agent]["embedding_dist_to_goal"].append(dist.item())
                results[agent]["reached"].append(reached)

                # roll the planner's history forward
                new_action = torch.tensor([[actions[agent][i]]], device=self.device)
                info[agent]["pixels"][i] = torch.cat(
                    [info[agent]["pixels"][i, 1:], frame[0]], dim=0
                )
                info[agent]["action"][i] = torch.cat(
                    [info[agent]["action"][i, 1:].unsqueeze(1), new_action], dim=0
                ).squeeze()

                if reached or truncated:
                    alive[agent][i] = False

        # message only conditions the very first planning call
        if real_step == 0:
            for agent in self.agents:
                info[agent].pop("msg_indices", None)
                info[agent].pop("csi", None)

    return results

